package zw.chibaro;
import java.util.*;import java.time.*;import java.sql.Timestamp;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.beans.factory.annotation.Value;
/** Durable leases: uncertain network outcomes are never blindly retried. Disabled in production until adapters are verified. */
@Component
public class PublishingWorker {
 final JdbcTemplate db;final TransactionTemplate tx;final List<PublishingAdapter> adapters;final boolean enabled;
 public PublishingWorker(JdbcTemplate db,TransactionTemplate tx,List<PublishingAdapter> adapters,@Value("${PUBLISHING_ENABLED:false}")boolean enabled){this.db=db;this.tx=tx;this.adapters=adapters;this.enabled=enabled;}
 @Scheduled(fixedDelayString="${PUBLISHING_POLL_MS:30000}") public void tick(){if(enabled)runOne();}
 public void runOne(){Map<String,Object> job=tx.execute(status->{db.update("update publishing_jobs set status='UNKNOWN',last_error='Worker lease expired; reconcile with provider before retrying' where status='PROCESSING' and lease_until<now()");var rows=db.queryForList("select * from publishing_jobs where status in ('PENDING','RETRY') and run_at<=now() order by run_at for update skip locked limit 1");if(rows.isEmpty())return null;var j=rows.getFirst();db.update("update publishing_jobs set status='PROCESSING',attempts=attempts+1,lease_until=now()+interval '2 minutes' where id=?",j.get("id"));return j;});if(job==null)return;
  PublishingAdapter.Result result;try{var posts=db.queryForList("select p.*,c.approved as campaign_approved from marketing_posts p join marketing_campaigns c on c.id=p.campaign_id where p.id=?",job.get("post_id"));var accounts=db.queryForList("select * from social_accounts where id=? and status='CONNECTED' and token_expires_at>now()",job.get("account_id"));if(posts.isEmpty()||accounts.isEmpty()||!Boolean.TRUE.equals(posts.getFirst().get("campaign_approved"))||!"SCHEDULED".equals(posts.getFirst().get("status")))result=PublishingAdapter.Result.setupRequired();else{var post=posts.getFirst();var account=accounts.getFirst();var adapter=adapters.stream().filter(a->a.provider().equals(account.get("provider"))&&a.provider().equals(post.get("platform"))).findFirst();if(adapter.isEmpty()||!adapter.get().eligible(post,account))result=PublishingAdapter.Result.setupRequired();else{MarketingService.policy(post.get("heading")+" "+post.get("caption")+" "+post.get("hashtags"));result=adapter.get().publish(post,account,job.get("id").toString());}}}catch(Exception ex){result=new PublishingAdapter.Result(PublishingAdapter.Outcome.UNKNOWN,null,"Uncertain provider outcome; manual reconciliation required",null);}
  final var outcome=result;tx.executeWithoutResult(status->{int attempts=((Number)job.get("attempts")).intValue()+1;String state=switch(outcome.outcome()){case SUCCESS->outcome.platformId()==null||outcome.platformId().isBlank()?"UNKNOWN":"SUCCEEDED";case RETRY_SAFE->attempts<5?"RETRY":"FAILED";case PERMANENT_FAILURE->"FAILED";case UNKNOWN->"UNKNOWN";};long delay=Math.min(3600,30L*(1L<<Math.min(attempts,6)));if(outcome.retryAfter()!=null)delay=Math.max(delay,Math.min(86400,outcome.retryAfter().toSeconds()));db.update("update publishing_jobs set status=?,run_at=?,lease_until=null,last_error=? where id=? and status='PROCESSING'",state,Timestamp.from(Instant.now().plusSeconds(delay)),outcome.safeError(),job.get("id"));db.update("insert into publishing_attempts(id,job_id,outcome,detail) values (?,?,?,?)",UUID.randomUUID(),job.get("id"),state,outcome.safeError());if(state.equals("SUCCEEDED"))db.update("update marketing_posts set status='PUBLISHED',platform_post_id=?,published_at=now() where id=?",outcome.platformId(),job.get("post_id"));else if(state.equals("FAILED")||state.equals("UNKNOWN")){db.update("update marketing_posts set status='FAILED' where id=?",job.get("post_id"));db.update("insert into notification_outbox(id,kind,resource_id) values (?,'PUBLISHING_REVIEW',?)",UUID.randomUUID(),job.get("post_id"));}SecurityConfig.audit(db,"scheduler","PUBLISH_"+state,job.get("id").toString());});
 }
}
